"""Stable Chinese labels for the public BMS parameter IDs."""

PARAMETER_CATALOG = {
    0x0101: ("单体过压保护", "mV"),
    0x0102: ("单体过压恢复", "mV"),
    0x0103: ("单体欠压保护", "mV"),
    0x0104: ("单体欠压恢复", "mV"),
    0x0105: ("保护延迟", "ms"),
    0x0110: ("充电过流保护", "mA"),
    0x0111: ("放电过流保护", "mA"),
    0x0120: ("充电低温保护", "0.1°C"),
    0x0121: ("充电高温保护", "0.1°C"),
    0x0122: ("放电低温保护", "0.1°C"),
    0x0123: ("放电高温保护", "0.1°C"),
    0x0130: ("单体压差告警", "mV"),
    0x0201: ("标称容量", "mAh"),
    0x0202: ("初始 SOC", "‰"),
    0x0301: ("均衡启动电压", "mV"),
    0x0302: ("均衡压差", "mV"),
    0x0303: ("均衡最低温度", "0.1°C"),
    0x0304: ("均衡最高温度", "0.1°C"),
    0x0305: ("均衡最大电流", "mA"),
    0x0401: ("加热启动温度", "0.1°C"),
    0x0402: ("加热停止温度", "0.1°C"),
}


def parameter_label(parameter_id: int) -> tuple[str, str]:
    return PARAMETER_CATALOG.get(parameter_id, ("未命名参数", ""))
